import{_ as e,o as d,c as n,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Comparison with LangChain / Eino / BeeAI","description":"","frontmatter":{"title":"Comparison with LangChain / Eino / BeeAI"},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md","lastUpdated":1783076988000}'),o={name:"comparison.md"};function r(i,t,s,l,h,p){return d(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="comparison-with-langchain-eino-beeai" tabindex="-1">Comparison with LangChain / Eino / BeeAI <a class="header-anchor" href="#comparison-with-langchain-eino-beeai" aria-label="Permalink to &quot;Comparison with LangChain / Eino / BeeAI&quot;">​</a></h1><p>Synapse is positioned as a Rust-native alternative to LangChain, Eino, and BeeAI, with unique strengths in cross-platform deployment, A2A protocols, and WASM sandboxing.</p><h2 id="feature-matrix" tabindex="-1">Feature Matrix <a class="header-anchor" href="#feature-matrix" aria-label="Permalink to &quot;Feature Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Synapse</th><th>LangChain</th><th>Eino</th><th>BeeAI</th></tr></thead><tbody><tr><td>Language</td><td>Rust</td><td>Python/JS</td><td>Go</td><td>Python/TypeScript</td></tr><tr><td>Governance</td><td>Apache 2.0</td><td>MIT</td><td>Apache 2.0</td><td>Linux Foundation</td></tr><tr><td>Runnable composition</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Graph workflows</td><td>✅</td><td>✅ (LangGraph)</td><td>✅</td><td>✅</td></tr><tr><td>ReAct agent (multi-turn)</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Streaming</td><td>⚠️ Partial</td><td>✅ Full</td><td>✅</td><td>✅</td></tr><tr><td>Tool middleware</td><td>✅</td><td>✅</td><td>✅</td><td>✅ Event-driven</td></tr><tr><td>Async native</td><td>✅</td><td>⚠️ Partial</td><td>✅</td><td>✅</td></tr><tr><td>Type safety</td><td>✅</td><td>❌ (Python)</td><td>✅</td><td>⚠️ (TS partial)</td></tr><tr><td>Performance</td><td>✅</td><td>⚠️</td><td>✅</td><td>⚠️</td></tr><tr><td>RAG (chunking)</td><td>✅ 4 splitters</td><td>✅ Many</td><td>✅</td><td>⚠️ External</td></tr><tr><td>RAG vector stores</td><td>⚠️ InMemory only</td><td>✅ 100+</td><td>⚠️ Few</td><td>⚠️ External</td></tr><tr><td>Embedding providers</td><td>⚠️ 3 (OpenAI/Anthropic/Azure)</td><td>✅ Many</td><td>✅ Many</td><td>✅ 10+</td></tr><tr><td>LLM providers</td><td>⚠️ 3</td><td>✅ Many</td><td>✅ Many</td><td>✅ 10+</td></tr><tr><td>Multi-agent</td><td>✅ 4 patterns</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>MCP</td><td>✅ stdio + HTTP</td><td>✅</td><td>❌</td><td>✅ Native</td></tr><tr><td>A2A protocol</td><td>✅</td><td>❌</td><td>❌</td><td>✅ Native</td></tr><tr><td>WASM deployment</td><td>✅ Native</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>Cross-platform (native + WASM)</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>Memory management</td><td>❌ (0.3.x)</td><td>✅</td><td>⚠️</td><td>✅ Built-in</td></tr><tr><td>OpenTelemetry observability</td><td>✅ Span/Trace (0.4)</td><td>✅</td><td>⚠️</td><td>✅ Native</td></tr><tr><td>Strongly-typed Lambda</td><td>✅ (0.4)</td><td>❌</td><td>✅</td><td>❌</td></tr><tr><td>LCEL-style pipe</td><td>✅ (0.4)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Declarative YAML orchestration</td><td>❌</td><td>⚠️ Partial</td><td>⚠️</td><td>✅</td></tr><tr><td>Built-in caching</td><td>❌</td><td>✅</td><td>⚠️</td><td>✅</td></tr><tr><td>Constraint enforcement</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Tests</td><td>~310</td><td>N/A</td><td>N/A</td><td>N/A</td></tr></tbody></table><h2 id="synapse-s-unique-strengths" tabindex="-1">Synapse&#39;s Unique Strengths <a class="header-anchor" href="#synapse-s-unique-strengths" aria-label="Permalink to &quot;Synapse&#39;s Unique Strengths&quot;">​</a></h2><ol><li><strong>A2A protocol</strong> — First-class cross-process agent communication.</li><li><strong>WASM sandbox</strong> — Deploy agents to sandboxed environments.</li><li><strong>MCP HTTP</strong> — Support both stdio and HTTP transports.</li><li><strong>MultiAgent coverage</strong> — All 4 patterns in one consistent API.</li><li><strong>Type safety</strong> — Rust&#39;s type system catches agent wiring errors at compile time.</li><li><strong>Strongly-typed Lambda</strong> — Eino-style type-safe composition (new in 0.4).</li><li><strong>LCEL-style pipe</strong> — LangChain-style chainable expressions (new in 0.4).</li><li><strong>Span/Trace observability</strong> — BeeAI-style tracing with pluggable exporters (new in 0.4).</li><li><strong>Apache 2.0</strong> — Open source license.</li></ol><h2 id="synapse-s-limitations" tabindex="-1">Synapse&#39;s Limitations <a class="header-anchor" href="#synapse-s-limitations" aria-label="Permalink to &quot;Synapse&#39;s Limitations&quot;">​</a></h2><ol><li><strong>Ecosystem</strong> — LangChain has 100+ integrations; Synapse has core components only.</li><li><strong>Vector stores</strong> — Currently in-memory only.</li><li><strong>Streaming</strong> — Partial support.</li><li><strong>Memory management</strong> — Not yet built-in (planned 0.3.x).</li><li><strong>OpenTelemetry exporter</strong> — Custom exporters needed for OTel (planned).</li><li><strong>Community</strong> — New project, smaller community.</li></ol><h2 id="new-in-0-4" tabindex="-1">New in 0.4 <a class="header-anchor" href="#new-in-0-4" aria-label="Permalink to &quot;New in 0.4&quot;">​</a></h2><ul><li><strong><a href="./guide/typed-lambda">Typed Lambda</a></strong> — Eino-style strongly-typed Lambda composition.</li><li><strong><a href="./guide/lcel-pipe">LCEL Pipe</a></strong> — LangChain-style chainable expressions.</li><li><strong><a href="./guide/observability">Observability</a></strong> — BeeAI-style Span/Trace with exporters.</li><li><strong><a href="./guide/framework-alignment">Framework Alignment</a></strong> — How Synapse aligns with Eino, BeeAI, LangChain.</li></ul><h2 id="when-to-choose-synapse" tabindex="-1">When to Choose Synapse <a class="header-anchor" href="#when-to-choose-synapse" aria-label="Permalink to &quot;When to Choose Synapse&quot;">​</a></h2><p>✅ Rust performance and type safety ✅ A2A protocol for cross-process agents ✅ Deploy agents in WASM sandboxes ✅ Apache 2.0 open source ✅ Building a multi-agent system</p><h2 id="when-to-choose-langchain" tabindex="-1">When to Choose LangChain <a class="header-anchor" href="#when-to-choose-langchain" aria-label="Permalink to &quot;When to Choose LangChain&quot;">​</a></h2><p>✅ Maximum ecosystem (100+ integrations) ✅ Python or JS ecosystem ✅ Mature, battle-tested production stack</p><h2 id="when-to-choose-eino" tabindex="-1">When to Choose Eino <a class="header-anchor" href="#when-to-choose-eino" aria-label="Permalink to &quot;When to Choose Eino&quot;">​</a></h2><p>✅ Prefer Go (Cloud Native ecosystem) ✅ Need deep ByteDance integration</p><h2 id="when-to-choose-beeai" tabindex="-1">When to Choose BeeAI <a class="header-anchor" href="#when-to-choose-beeai" aria-label="Permalink to &quot;When to Choose BeeAI&quot;">​</a></h2><p>✅ Linux Foundation governance with vendor-neutral open source ✅ Python or TypeScript with full feature parity ✅ Built-in memory management (unbounded / summarized / token-windowed) ✅ Declarative YAML-based agent orchestration ✅ Production-grade constraint enforcement + caching ✅ Native OpenTelemetry observability out of the box ✅ MCP and A2A interop as first-class citizens</p>',18)])])}const m=e(o,[["render",r]]);export{g as __pageData,m as default};
